2. using Microsoft.Extensions.DependencyInjection;
3. using Microsoft.Extensions.Hosting;
4. using Microsoft.Extensions.Logging;
5. using Microsoft.EntityFrameworkCore;
6. using ContosoUniversity.Data;
7. using Microsoft.Extensions.Configuration;
8. using System;
9. using System.IO;
10. 
11. var builder = WebApplication.CreateBuilder(args);
12. 
13. // Add Entity Framework
14. builder.Services.AddDbContext<SchoolContext>(options =>
15.     options.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection"),
16.         sqlServerOptionsAction: sqlOptions =>
17.         {
18.             sqlOptions.EnableRetryOnFailure(
19.                 maxRetryCount: 5,
20.                 maxRetryDelay: TimeSpan.FromSeconds(30),
21.                 errorNumbersToAdd: null);
22.         }));
23. 
24. // Add MVC services
25. builder.Services.AddControllersWithViews();
26. builder.Services.AddSession();
27. 
28. var app = builder.Build();
29. 
30. // Initialize database
31. using (var scope = app.Services.CreateScope())
32. {
33.     var services = scope.ServiceProvider;
34.     try
35.     {
36.         var context = services.GetRequiredService<SchoolContext>();
37.         DbInitializer.Initialize(context);
38.     }
39.     catch (Exception ex)
40.     {
41.         var logger = services.GetRequiredService<ILogger<Program>>();
42.         logger.LogError(ex, "An error occurred creating the DB.");
43.     }
44. }
45. 
46. if (!app.Environment.IsDevelopment())
47. {
48.     app.UseHsts();
49. }
50. 
51. app.UseHttpsRedirection();
52. app.UseStaticFiles(); // For wwwroot
53. 
54. // Serve legacy Content folder
55. app.UseStaticFiles(new StaticFileOptions
56. {
57.     FileProvider = new Microsoft.Extensions.FileProviders.PhysicalFileProvider(
58.         Path.Combine(builder.Environment.ContentRootPath, "Content")),
59.     RequestPath = "/Content"
60. });
61. 
62. // Serve legacy Scripts folder  
63. app.UseStaticFiles(new StaticFileOptions
64. {
65.     FileProvider = new Microsoft.Extensions.FileProviders.PhysicalFileProvider(
66.         Path.Combine(builder.Environment.ContentRootPath, "Scripts")),
67.     RequestPath = "/Scripts"
68. });
69. 
70. app.UseRouting();
71. app.UseSession();
72. 
73. app.MapControllerRoute(
74.     name: "default",
75.     pattern: "{controller=Home}/{action=Index}/{id?}");
76. 
77. app.Run();

