using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests;

public static class TestHelper
{
    public static SchoolContext CreateContext(string? dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
        return new SchoolContext(options);
    }

    public static void SeedStudents(SchoolContext context)
    {
        context.Students.AddRange(
            new Student { FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2010-09-01") },
            new Student { FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2012-09-01") },
            new Student { FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2013-09-01") }
        );
        context.SaveChanges();
    }

    public static void SeedInstructors(SchoolContext context)
    {
        context.Instructors.AddRange(
            new Instructor { FirstMidName = "Kim", LastName = "Abercrombie", HireDate = DateTime.Parse("1995-03-11") },
            new Instructor { FirstMidName = "Fadi", LastName = "Fakhouri", HireDate = DateTime.Parse("2002-07-06") }
        );
        context.SaveChanges();
    }

    public static void SeedDepartments(SchoolContext context)
    {
        SeedInstructors(context);
        var instructor = context.Instructors.First(i => i.LastName == "Abercrombie");
        context.Departments.AddRange(
            new Department { Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructor.ID },
            new Department { Name = "Mathematics", Budget = 100000, StartDate = DateTime.Parse("2007-09-01") }
        );
        context.SaveChanges();
    }

    public static void SeedCourses(SchoolContext context)
    {
        SeedDepartments(context);
        var dept = context.Departments.First(d => d.Name == "English");
        context.Courses.AddRange(
            new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = dept.DepartmentID },
            new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = dept.DepartmentID }
        );
        context.SaveChanges();
    }

    public static void SeedFullData(SchoolContext context)
    {
        SeedCourses(context);
        SeedStudents(context);

        var student = context.Students.First();
        var course = context.Courses.First();
        context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A });
        context.SaveChanges();
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        _service = new NotificationService();
        // Drain any leftover notifications from previous tests (static queue)
        while (_service.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        _service.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotification()
    {
        _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("John Doe", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
    {
        _service.SendNotification("Course", "42", EntityOperation.UPDATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Course", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("UPDATE", notification.Operation);
        Assert.Contains("ID: 42", notification.Message);
        Assert.Contains("updated", notification.Message);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_Delete_GeneratesDeleteMessage()
    {
        _service.SendNotification("Department", "5", "Math", EntityOperation.DELETE, "teacher");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Contains("deleted", notification.Message);
        Assert.Contains("Math", notification.Message);
        Assert.Equal("teacher", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_DefaultUser_SetsSystemAsCreatedBy()
    {
        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var result = _service.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_FIFO_Order()
    {
        _service.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _service.SendNotification("B", "2", "Second", EntityOperation.UPDATE);

        var first = _service.ReceiveNotification();
        var second = _service.ReceiveNotification();

        Assert.NotNull(first);
        Assert.NotNull(second);
        Assert.Equal("A", first.EntityType);
        Assert.Equal("B", second.EntityType);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToNow()
    {
        var before = DateTime.Now.AddSeconds(-1);
        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
        var after = DateTime.Now.AddSeconds(1);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void SendNotification_SetsIsReadToFalse()
    {
        _service.SendNotification("Student", "1", EntityOperation.CREATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op in the in-memory implementation
        var exception = Record.Exception(() => _service.MarkAsRead(999));
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesEntityIdFormat()
    {
        _service.SendNotification("Student", "99", "", EntityOperation.UPDATE, "admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("ID: 99", notification.Message);
    }

    [Fact]
    public void SendNotification_MultipleMessages_AllDequeued()
    {
        for (int i = 0; i < 5; i++)
        {
            _service.SendNotification("Entity", i.ToString(), $"Name{i}", EntityOperation.CREATE);
        }

        var notifications = new List<Notification>();
        Notification? n;
        while ((n = _service.ReceiveNotification()) != null)
        {
            notifications.Add(n);
        }

        Assert.Equal(5, notifications.Count);
        for (int i = 0; i < 5; i++)
        {
            Assert.Equal(i.ToString(), notifications[i].EntityId);
            Assert.Equal($"Name{i}", notifications[i].Message.Contains($"Name{i}") ? $"Name{i}" : "");
        }
    }
}

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Create_FirstPage_ReturnsCorrectItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_SecondPage_ReturnsCorrectItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 2, 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(11, result[0]);
        Assert.Equal(20, result[9]);
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 3, 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(3, result.PageIndex);
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();
        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();
        var result = PaginatedList<int>.Create(source, 2, 10);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_FirstPage_ReturnsTrue()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();
        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_LastPage_ReturnsFalse()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();
        var result = PaginatedList<int>.Create(source, 3, 10);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Empty(result);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(0, result.TotalPages);
    }

    [Fact]
    public void Create_ExactPageSize_SinglePage()
    {
        var source = Enumerable.Range(1, 10).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void TotalPages_CalculatedCorrectly_WithRemainder()
    {
        // 11 items, page size 5 -> 3 pages (ceil(11/5) = 3)
        var source = Enumerable.Range(1, 11).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 5);

        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void Constructor_SetsPropertiesCorrectly()
    {
        var items = new List<string> { "a", "b", "c" };

        var list = new PaginatedList<string>(items, 30, 2, 10);

        Assert.Equal(2, list.PageIndex);
        Assert.Equal(3, list.TotalPages);
        Assert.Equal(3, list.Count);
        Assert.Contains("a", list);
        Assert.Contains("b", list);
        Assert.Contains("c", list);
    }
}

