using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestHelper.CreateContext();
        _controller = new NotificationsController(_context);
        // Drain any leftover notifications from previous tests
        var service = new NotificationService();
        while (service.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
    {
        var result = _controller.GetNotifications();

        Assert.NotNull(result);
        var jsonResult = Assert.IsType<JsonResult>(result);
        Assert.NotNull(jsonResult.Value);

        // Use dynamic to inspect anonymous type
        var value = jsonResult.Value;
        var successProp = value.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");

        Assert.NotNull(successProp);
        Assert.NotNull(countProp);
        Assert.Equal(true, successProp.GetValue(value));
        Assert.Equal(0, countProp.GetValue(value));
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsThemAll()
    {
        // Enqueue some notifications via the service (shared static queue)
        var service = new NotificationService();
        service.SendNotification("Student", "1", "John", EntityOperation.CREATE);
        service.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);

        var result = _controller.GetNotifications();

        Assert.NotNull(result);
        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");
        var notificationsProp = value.GetType().GetProperty("notifications");

        Assert.Equal(true, successProp!.GetValue(value));
        var count = (int)countProp!.GetValue(value)!;
        Assert.True(count >= 2);
    }

    [Fact]
    public void GetNotifications_LimitsTo10()
    {
        var service = new NotificationService();
        for (int i = 0; i < 15; i++)
        {
            service.SendNotification("Entity", i.ToString(), $"Name{i}", EntityOperation.CREATE);
        }

        var result = _controller.GetNotifications();

        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var countProp = value.GetType().GetProperty("count");
        var count = (int)countProp!.GetValue(value)!;
        Assert.True(count <= 10);
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccess()
    {
