+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+
+namespace ContosoUniversity.Tests;
+
+public class NotificationServiceTests : IDisposable
+{
+    private readonly NotificationService _service;
+
+    public NotificationServiceTests()
+    {
+        _service = new NotificationService();
+        // Drain any leftover notifications from previous tests (static queue)
+        while (_service.ReceiveNotification() != null) { }
+    }
+
+    public void Dispose()
+    {
+        _service.Dispose();
+    }
+
+    [Fact]
+    public void SendNotification_WithDisplayName_EnqueuesNotification()
+    {
+        _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Equal("Student", notification.EntityType);
+        Assert.Equal("1", notification.EntityId);
+        Assert.Equal("CREATE", notification.Operation);
+        Assert.Contains("John Doe", notification.Message);
+        Assert.Contains("created", notification.Message);
+        Assert.Equal("admin", notification.CreatedBy);
+        Assert.False(notification.IsRead);
+    }
+
+    [Fact]
+    public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
+    {
+        _service.SendNotification("Course", "42", EntityOperation.UPDATE);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Equal("Course", notification.EntityType);
+        Assert.Equal("42", notification.EntityId);
+        Assert.Equal("UPDATE", notification.Operation);
+        Assert.Contains("ID: 42", notification.Message);
+        Assert.Contains("updated", notification.Message);
+        Assert.Equal("System", notification.CreatedBy);
+    }
+
+    [Fact]
+    public void SendNotification_Delete_GeneratesDeleteMessage()
+    {
+        _service.SendNotification("Department", "5", "Math", EntityOperation.DELETE, "teacher");
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Equal("DELETE", notification.Operation);
+        Assert.Contains("deleted", notification.Message);
+        Assert.Contains("Math", notification.Message);
+        Assert.Equal("teacher", notification.CreatedBy);
+    }
+
+    [Fact]
+    public void SendNotification_DefaultUser_SetsSystemAsCreatedBy()
+    {
+        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Equal("System", notification.CreatedBy);
+    }
+
+    [Fact]
+    public void ReceiveNotification_EmptyQueue_ReturnsNull()
+    {
+        var result = _service.ReceiveNotification();
+        Assert.Null(result);
+    }
+
+    [Fact]
+    public void ReceiveNotification_FIFO_Order()
+    {
+        _service.SendNotification("A", "1", "First", EntityOperation.CREATE);
+        _service.SendNotification("B", "2", "Second", EntityOperation.UPDATE);
+
+        var first = _service.ReceiveNotification();
+        var second = _service.ReceiveNotification();
+
+        Assert.NotNull(first);
+        Assert.NotNull(second);
+        Assert.Equal("A", first.EntityType);
+        Assert.Equal("B", second.EntityType);
+    }
+
+    [Fact]
+    public void SendNotification_SetsCreatedAtToNow()
+    {
+        var before = DateTime.Now.AddSeconds(-1);
+        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
+        var after = DateTime.Now.AddSeconds(1);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.InRange(notification.CreatedAt, before, after);
+    }
+
+    [Fact]
+    public void SendNotification_SetsIsReadToFalse()
+    {
+        _service.SendNotification("Student", "1", EntityOperation.CREATE);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.False(notification.IsRead);
+    }
+
+    [Fact]
+    public void MarkAsRead_DoesNotThrow()
+    {
+        // MarkAsRead is a no-op in the in-memory implementation
+        var exception = Record.Exception(() => _service.MarkAsRead(999));
+        Assert.Null(exception);
+    }
+
+    [Fact]
+    public void Dispose_DoesNotThrow()
+    {
+        var service = new NotificationService();
+        var exception = Record.Exception(() => service.Dispose());
+        Assert.Null(exception);
+    }
+
+    [Fact]
+    public void SendNotification_WithNullUserName_DefaultsToSystem()
+    {
+        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Equal("System", notification.CreatedBy);
+    }
+
+    [Fact]
+    public void SendNotification_WithEmptyDisplayName_UsesEntityIdFormat()
+    {
+        _service.SendNotification("Student", "99", "", EntityOperation.UPDATE, "admin");
+
+        var notification = _service.ReceiveNotification();
+
+        Assert.NotNull(notification);
+        Assert.Contains("ID: 99", notification.Message);
+    }
+
+    [Fact]
+    public void SendNotification_MultipleMessages_AllDequeued()
+    {
+        for (int i = 0; i < 5; i++)
+        {
+            _service.SendNotification("Entity", i.ToString(), $"Name{i}", EntityOperation.CREATE);
+        }
+
+        var notifications = new List<Notification>();
+        Notification? n;
+        while ((n = _service.ReceiveNotification()) != null)
+        {
+            notifications.Add(n);
+        }
+
+        Assert.Equal(5, notifications.Count);
+        for (int i = 0; i < 5; i++)
+        {
+            Assert.Equal(i.ToString(), notifications[i].EntityId);
+            Assert.Equal($"Name{i}", notifications[i].Message.Contains($"Name{i}") ? $"Name{i}" : "");
+        }
+    }
+}
+

