+    {
+        using var context = TestHelper.CreateContext();
+        var student = new Student
+        {
+            FirstMidName = "Test",
+            LastName = "Student",
+            EnrollmentDate = new DateTime(2023, 9, 1)
+        };
+
+        context.Students.Add(student);
+        context.SaveChanges();
+
+        var retrieved = context.Students.Single(s => s.LastName == "Student");
+        Assert.Equal("Test", retrieved.FirstMidName);
+        Assert.Equal(new DateTime(2023, 9, 1), retrieved.EnrollmentDate);
+        Assert.True(retrieved.ID > 0);
+    }
+
+    [Fact]
+    public void Context_CanAddAndRetrieveInstructor()
+    {
+        using var context = TestHelper.CreateContext();
+        var instructor = new Instructor
+        {
+            FirstMidName = "Jane",
+            LastName = "Smith",
+            HireDate = new DateTime(2020, 1, 15)
+        };
+
+        context.Instructors.Add(instructor);
+        context.SaveChanges();
+
+        var retrieved = context.Instructors.Single(i => i.LastName == "Smith");
+        Assert.Equal("Jane", retrieved.FirstMidName);
+        Assert.Equal(new DateTime(2020, 1, 15), retrieved.HireDate);
+    }
+
+    [Fact]
+    public void Context_CanAddCourseWithDepartment()
+    {
+        using var context = TestHelper.CreateContext();
+        var dept = new Department
+        {
+            Name = "Science",
+            Budget = 200000,
+            StartDate = DateTime.Now
+        };
+        context.Departments.Add(dept);
+        context.SaveChanges();
+
+        var course = new Course
+        {
+            CourseID = 1001,
+            Title = "Physics",
+            Credits = 4,
+            DepartmentID = dept.DepartmentID
+        };
+        context.Courses.Add(course);
+        context.SaveChanges();
+
+        var retrieved = context.Courses
+            .Include(c => c.Department)
+            .Single(c => c.CourseID == 1001);
+
+        Assert.Equal("Physics", retrieved.Title);
+        Assert.Equal(4, retrieved.Credits);
+        Assert.Equal("Science", retrieved.Department.Name);
+    }
+
+    [Fact]
+    public void Context_CourseAssignment_CompositeKey()
+    {
+        using var context = TestHelper.CreateContext();
+        var instructor = new Instructor
+        {
+            FirstMidName = "Test",
+            LastName = "Instructor",
+            HireDate = DateTime.Now
+        };
+        context.Instructors.Add(instructor);
+        context.SaveChanges();
+
+        var dept = new Department
+        {
+            Name = "TestDept",
+            Budget = 100000,
+            StartDate = DateTime.Now
+        };
+        context.Departments.Add(dept);
+        context.SaveChanges();
+
+        var course = new Course
+        {
+            CourseID = 2001,
+            Title = "TestCourse",
+            Credits = 3,
+            DepartmentID = dept.DepartmentID
+        };
+        context.Courses.Add(course);
+        context.SaveChanges();
+
+        var assignment = new CourseAssignment
+        {
+            CourseID = course.CourseID,
+            InstructorID = instructor.ID
+        };
+        context.CourseAssignments.Add(assignment);
+        context.SaveChanges();
+
+        var retrieved = context.CourseAssignments
+            .Include(ca => ca.Course)
+            .Include(ca => ca.Instructor)
+            .Single(ca => ca.CourseID == course.CourseID && ca.InstructorID == instructor.ID);
+
+        Assert.Equal("TestCourse", retrieved.Course.Title);
+        Assert.Equal("Instructor", retrieved.Instructor.LastName);
+    }
+
+    [Fact]
+    public void Context_Enrollment_RelationshipsWork()
+    {
+        using var context = TestHelper.CreateContext();
+        var student = new Student
+        {
+            FirstMidName = "Enroll",
+            LastName = "Test",
+            EnrollmentDate = DateTime.Now
+        };
+        context.Students.Add(student);
+
+        var dept = new Department { Name = "Dept", Budget = 10000, StartDate = DateTime.Now };
+        context.Departments.Add(dept);
+        context.SaveChanges();
+
+        var course = new Course
+        {
+            CourseID = 3001,
+            Title = "EnrollCourse",
+            Credits = 3,
+            DepartmentID = dept.DepartmentID
+        };
+        context.Courses.Add(course);
+        context.SaveChanges();
+
+        var enrollment = new Enrollment
+        {
+            StudentID = student.ID,
+            CourseID = course.CourseID,
+            Grade = Grade.B
+        };
+        context.Enrollments.Add(enrollment);
+        context.SaveChanges();
+
+        var retrieved = context.Enrollments
+            .Include(e => e.Student)
+            .Include(e => e.Course)
+            .Single(e => e.StudentID == student.ID);
+
+        Assert.Equal(Grade.B, retrieved.Grade);
+        Assert.Equal("Test", retrieved.Student.LastName);
+        Assert.Equal("EnrollCourse", retrieved.Course.Title);
+    }
+
+    [Fact]
+    public void Context_OfficeAssignment_OneToOne()
+    {
+        using var context = TestHelper.CreateContext();
+        var instructor = new Instructor
+        {
+            FirstMidName = "Office",
+            LastName = "Test",
+            HireDate = DateTime.Now,
+            OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
+        };
+        context.Instructors.Add(instructor);
+        context.SaveChanges();
+
+        var retrieved = context.Instructors
+            .Include(i => i.OfficeAssignment)
+            .Single(i => i.LastName == "Test");
+
+        Assert.NotNull(retrieved.OfficeAssignment);
+        Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
+        Assert.Equal(instructor.ID, retrieved.OfficeAssignment.InstructorID);
+    }
+}
