using ContosoUniversity.Models;
using ContosoUniversity.Services;
using System;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain the static queue to isolate tests
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_EnqueuesNotification()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE, "TestUser");
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("TestUser", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithDisplayName_IncludesInMessage()
        {
            _service.SendNotification("Course", "101", "Chemistry", EntityOperation.CREATE, "Admin");
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("Chemistry", notification.Message);
            Assert.Contains("Course", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityId()
        {
            _service.SendNotification("Student", "42", EntityOperation.CREATE);
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("42", notification.Message);
        }

        [Fact]
        public void SendNotification_DefaultsToSystemUser_WhenNoUsername()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE);
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_CreateOperation_Message()
        {
            _service.SendNotification("Student", "1", "John", EntityOperation.CREATE);
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("created", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_Message()
        {
            _service.SendNotification("Student", "1", "John", EntityOperation.UPDATE);
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_Message()
        {
            _service.SendNotification("Student", "1", "John", EntityOperation.DELETE);
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("deleted", notification.Message);
        }

        [Fact]
        public void ReceiveNotification_ReturnsNull_WhenQueueIsEmpty()
        {
            var notification = _service.ReceiveNotification();
            Assert.Null(notification);
        }

        [Fact]
        public void ReceiveNotification_ReturnsInFIFOOrder()
        {
            _service.SendNotification("Type1", "1", EntityOperation.CREATE);
            _service.SendNotification("Type2", "2", EntityOperation.UPDATE);

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();

            Assert.Equal("Type1", first!.EntityType);
            Assert.Equal("Type2", second!.EntityType);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _service.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_SetsCreatedAt()
        {
            var before = DateTime.Now;
            _service.SendNotification("Test", "1", EntityOperation.CREATE);
            var after = DateTime.Now;

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void SendNotification_TwoArgOverload_Works()
        {
            _service.SendNotification("Dept", "5", EntityOperation.DELETE, "Admin");
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Dept", notification.EntityType);
            Assert.Equal("DELETE", notification.Operation);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }
    }
}

using ContosoUniversity.Models;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var page = PaginatedList<int>.Create(items, 1, 10);
            Assert.Equal(10, page.Count);
            Assert.Equal(1, page.PageIndex);
            Assert.Equal(3, page.TotalPages);
        }

        [Fact]
        public void Create_ReturnsSecondPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var page = PaginatedList<int>.Create(items, 2, 10);
            Assert.Equal(10, page.Count);
            Assert.Equal(11, page[0]);
        }

        [Fact]
        public void Create_ReturnsLastPartialPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var page = PaginatedList<int>.Create(items, 3, 10);
            Assert.Equal(5, page.Count);
        }

        [Fact]
        public void HasPreviousPage_FalseOnFirstPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var page = PaginatedList<int>.Create(items, 1, 10);
            Assert.False(page.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_TrueOnSecondPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var page = PaginatedList<int>.Create(items, 2, 10);
            Assert.True(page.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_TrueOnFirstPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var page = PaginatedList<int>.Create(items, 1, 10);
            Assert.True(page.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FalseOnLastPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var page = PaginatedList<int>.Create(items, 3, 10);
            Assert.False(page.HasNextPage);
        }

        [Fact]
        public void TotalPages_CalculatedCorrectly()
        {
            var items = Enumerable.Range(1, 1).AsQueryable();
            var page = PaginatedList<int>.Create(items, 1, 10);
            Assert.Equal(1, page.TotalPages);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyPage()
        {
            var items = Enumerable.Empty<int>().AsQueryable();
            var page = PaginatedList<int>.Create(items, 1, 10);
            Assert.Empty(page);
            Assert.Equal(0, page.TotalPages);
        }

        [Fact]
        public void Constructor_SetsProperties()
        {
            var list = new List<string> { "a", "b" };
            var page = new PaginatedList<string>(list, 10, 2, 5);
            Assert.Equal(2, page.PageIndex);
            Assert.Equal(2, page.TotalPages);
            Assert.Equal(2, page.Count);
        }
    }
}

