using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
            _controller = new StudentsController(_context);
            TestHelpers.SetupControllerContext(_controller);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        #region Index

        [Fact]
        public void Index_ReturnsView_WithStudents()
        {
            TestHelpers.SeedStudents(_context);
            var result = _controller.Index(null, null, null, null) as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(3, model.Count);
        }

        [Fact]
        public void Index_SortsByLastNameAscending_ByDefault()
        {
            TestHelpers.SeedStudents(_context);
            var result = _controller.Index(null, null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Anderson", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Clark", model[2].LastName);
        }

        [Fact]
        public void Index_SortsByLastNameDescending_WhenNameDescSort()
        {
            TestHelpers.SeedStudents(_context);
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Clark", model[0].LastName);
        }

        [Fact]
        public void Index_SortsByDateAscending()
        {
            TestHelpers.SeedStudents(_context);
            var result = _controller.Index("Date", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Anderson", model[0].LastName);
        }

        [Fact]
        public void Index_SortsByDateDescending()
        {
            TestHelpers.SeedStudents(_context);
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Clark", model[0].LastName);
        }

        [Fact]
        public void Index_FiltersStudentsBySearchString()
        {
            TestHelpers.SeedStudents(_context);
            var result = _controller.Index(null, null, "Baker", null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Baker", model[0].LastName);
        }

        [Fact]
        public void Index_FiltersStudentsByFirstName()
        {
            TestHelpers.SeedStudents(_context);
            var result = _controller.Index(null, null, "Alice", null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Anderson", model[0].LastName);
        }

        [Fact]
        public void Index_UsesCurrentFilter_WhenSearchStringIsNull()
        {
            TestHelpers.SeedStudents(_context);
            var result = _controller.Index(null, "Baker", null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
        }

        [Fact]
        public void Index_SetsViewBagSortParams()
        {
            TestHelpers.SeedStudents(_context);
            var result = _controller.Index(null, null, null, null) as ViewResult;
            Assert.NotNull(result);
            Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
            Assert.Equal("Date", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_SetsPage1_WhenNewSearchString()
        {
            TestHelpers.SeedStudents(_context);
            _controller.Index(null, null, "Alice", 3);
            // When searchString != null, page is reset to 1 internally
            Assert.NotNull(_controller.ViewBag.CurrentFilter);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_ReturnsNotFound_WhenIdIsNull()
        {
            var result = _controller.Details(null);
            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Details_ReturnsView_WithStudent()
        {
            TestHelpers.SeedStudents(_context);
            var student = _context.Students.First();
            // Add enrollment data for the Include to work
            var dept = new Department { Name = "Test", Budget = 100, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            var course = new Course { CourseID = 9999, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A });
            _context.SaveChanges();

            var result = _controller.Details(student.ID) as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.LastName, model.LastName);
        }

        #endregion

        #region Create GET

        [Fact]
        public void Create_Get_ReturnsView_WithDefaultEnrollmentDate()
        {
            var result = _controller.Create() as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        #endregion

        #region Create POST

        [Fact]
        public void Create_Post_AddsStudentAndRedirects_WhenModelIsValid()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Single(_context.Students);
        }

