using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class DepartmentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly DepartmentsController _controller;

        public DepartmentsControllerTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
            _controller = new DepartmentsController(_context);
            TestHelpers.SetupControllerContext(_controller);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        #region Index

        [Fact]
        public void Index_ReturnsView_WithDepartments()
        {
            TestHelpers.SeedDepartments(_context);
            var result = _controller.Index() as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Department>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_ReturnsBadRequest_WhenIdIsNull()
        {
            var result = _controller.Details(null);
            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Details_ReturnsNotFound_WhenDepartmentDoesNotExist()
        {
            var result = _controller.Details(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ReturnsView_WithDepartment()
        {
            TestHelpers.SeedDepartments(_context);
            var dept = _context.Departments.First();
            var result = _controller.Details(dept.DepartmentID) as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsType<Department>(result.Model);
            Assert.Equal(dept.Name, model.Name);
        }

        #endregion

        #region Create GET

        [Fact]
        public void Create_Get_ReturnsView_WithInstructorSelectList()
        {
            TestHelpers.SeedInstructors(_context);
            var result = _controller.Create() as ViewResult;
            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.InstructorID);
        }

        #endregion

        #region Create POST

        [Fact]
        public void Create_Post_AddsDepartmentAndRedirects_WhenValid()
        {
            TestHelpers.SeedInstructors(_context);
            var dept = new Department
            {
                Name = "Physics",
                Budget = 200000,
                StartDate = new DateTime(2020, 1, 1)
            };

            var result = _controller.Create(dept) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Single(_context.Departments);
        }

        [Fact]
        public void Create_Post_ReturnsView_WhenModelStateInvalid()
        {
            TestHelpers.SeedInstructors(_context);
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = new Department { Budget = 100000, StartDate = DateTime.Now };

            var result = _controller.Create(dept) as ViewResult;
            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.InstructorID);
        }

        #endregion

        #region Edit GET

        [Fact]
        public void Edit_Get_ReturnsBadRequest_WhenIdIsNull()
        {
            var result = _controller.Edit((int?)null);
            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Edit_Get_ReturnsNotFound_WhenDepartmentDoesNotExist()
        {
            var result = _controller.Edit(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ReturnsView_WithDepartment()
        {
            TestHelpers.SeedDepartments(_context);
            var dept = _context.Departments.First();
            var result = _controller.Edit(dept.DepartmentID) as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsType<Department>(result.Model);
            Assert.Equal(dept.Name, model.Name);
        }

        #endregion

        #region Edit POST

        [Fact]
        public void Edit_Post_UpdatesAndRedirects_WhenValid()
        {
            TestHelpers.SeedDepartments(_context);
            var dept = _context.Departments.First();
            _context.Entry(dept).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = new Department
            {
                DepartmentID = dept.DepartmentID,
                Name = "Updated",
                Budget = 500000,
                StartDate = dept.StartDate,
                InstructorID = dept.InstructorID
            };

            var result = _controller.Edit(updated) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_Post_ReturnsView_WhenModelStateInvalid()
        {
            TestHelpers.SeedDepartments(_context);
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = new Department { DepartmentID = 1, Budget = 100000, StartDate = DateTime.Now };

            var result = _controller.Edit(dept) as ViewResult;
            Assert.NotNull(result);
        }

        #endregion

        #region Delete GET

        [Fact]
        public void Delete_Get_ReturnsBadRequest_WhenIdIsNull()
        {
            var result = _controller.Delete(null);
            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Delete_Get_ReturnsNotFound_WhenDepartmentDoesNotExist()
        {
            var result = _controller.Delete(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ReturnsView_WithDepartment()
        {
            TestHelpers.SeedDepartments(_context);
            var dept = _context.Departments.First();
            var result = _controller.Delete(dept.DepartmentID) as ViewResult;
            Assert.NotNull(result);
        }

        #endregion

        #region DeleteConfirmed

        [Fact]
        public void DeleteConfirmed_RemovesDepartmentAndRedirects()
        {
            TestHelpers.SeedDepartments(_context);
            var dept = _context.Departments.First();
            var result = _controller.DeleteConfirmed(dept.DepartmentID) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Single(_context.Departments);
        }

        #endregion
    }
}

