using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
            _controller = new InstructorsController(_context);
            TestHelpers.SetupControllerContext(_controller);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private void SeedInstructorsWithCourses()
        {
            TestHelpers.SeedCourses(_context);
            var instructor = _context.Instructors.First();
            var course = _context.Courses.First();
            _context.CourseAssignments.Add(new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            });
            _context.SaveChanges();

            // Add an enrollment to the course
            var student = new Student { FirstMidName = "Test", LastName = "Student", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            _context.SaveChanges();
            _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A });
            _context.SaveChanges();
        }

        #region Index

        [Fact]
        public void Index_ReturnsView_WithInstructorData()
        {
            TestHelpers.SeedInstructors(_context);
            var result = _controller.Index(null, null) as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_ShowsCourses()
        {
            SeedInstructorsWithCourses();
            var instructor = _context.Instructors.First();
            var result = _controller.Index(instructor.ID, null) as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Courses);
            Assert.NotEmpty(model.Courses);
        }

        [Fact]
        public void Index_WithCourseId_ShowsEnrollments()
        {
            SeedInstructorsWithCourses();
            var instructor = _context.Instructors.First();
            var course = _context.Courses.First();
            var result = _controller.Index(instructor.ID, course.CourseID) as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Enrollments);
            Assert.NotEmpty(model.Enrollments);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_ReturnsBadRequest_WhenIdIsNull()
        {
            var result = _controller.Details(null);
            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Details_ReturnsNotFound_WhenInstructorDoesNotExist()
        {
            var result = _controller.Details(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ReturnsView_WithInstructor()
        {
            TestHelpers.SeedInstructors(_context);
            var instructor = _context.Instructors.First();
            var result = _controller.Details(instructor.ID) as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal(instructor.LastName, model.LastName);
        }

        #endregion

        #region Create GET

        [Fact]
        public void Create_Get_ReturnsView_WithNewInstructor()
        {
            var result = _controller.Create() as ViewResult;
            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
        }

        #endregion

        #region Create POST

        [Fact]
        public void Create_Post_AddsInstructorAndRedirects_WhenValid()
        {
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2020, 1, 1)
            };

            var result = _controller.Create(instructor, null) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Single(_context.Instructors);
        }

        [Fact]
        public void Create_Post_AddsInstructorWithCourses()
        {
            TestHelpers.SeedCourses(_context);
            var course = _context.Courses.First();
            var existingCount = _context.Instructors.Count();

            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2020, 1, 1)
            };

            var result = _controller.Create(instructor, new[] { course.CourseID.ToString() }) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal(existingCount + 1, _context.Instructors.Count());
        }

        [Fact]
        public void Create_Post_ReturnsView_WhenModelStateInvalid()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                HireDate = new DateTime(2020, 1, 1)
            };

            var result = _controller.Create(instructor, null) as ViewResult;
            Assert.NotNull(result);
        }

        #endregion

        #region Edit GET

        [Fact]
        public void Edit_Get_ReturnsBadRequest_WhenIdIsNull()
        {
            var result = _controller.Edit((int?)null);
            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Edit_Get_ReturnsView_WithInstructor()
        {
            SeedInstructorsWithCourses();
            var instructor = _context.Instructors.First();
            var result = _controller.Edit(instructor.ID) as ViewResult;
            Assert.NotNull(result);
        }

        #endregion

        #region Delete GET

        [Fact]
        public void Delete_Get_ReturnsBadRequest_WhenIdIsNull()
        {
            var result = _controller.Delete(null);
            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Delete_Get_ReturnsNotFound_WhenInstructorDoesNotExist()
        {
            var result = _controller.Delete(999);
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ReturnsView_WithInstructor()
        {
            TestHelpers.SeedInstructors(_context);
            var instructor = _context.Instructors.First();
            var result = _controller.Delete(instructor.ID) as ViewResult;
            Assert.NotNull(result);
        }

        #endregion

        #region DeleteConfirmed

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndRedirects()
        {
            SeedInstructorsWithCourses();
            var instructor = _context.Instructors.First();
            // Ensure the instructor has an office assignment
            _context.OfficeAssignments.Add(new OfficeAssignment { InstructorID = instructor.ID, Location = "Test Office" });
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void DeleteConfirmed_NullsDepartmentAdministrator()
        {
            TestHelpers.SeedDepartments(_context);
            var instructor = _context.Instructors.First();
            var dept = _context.Departments.First(d => d.InstructorID == instructor.ID);
            // Add office assignment for the instructor (required by Delete query)
            _context.OfficeAssignments.Add(new OfficeAssignment { InstructorID = instructor.ID, Location = "Office" });
            _context.SaveChanges();

            _controller.DeleteConfirmed(instructor.ID);
            var updatedDept = _context.Departments.Find(dept.DepartmentID);
            Assert.Null(updatedDept!.InstructorID);
        }

        #endregion
    }
}

