using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.First();
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal("Student", retrieved.LastName);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = new DateTime(2020, 1, 1)
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var retrieved = _context.Instructors.First();
            Assert.Equal("Test", retrieved.FirstMidName);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            TestHelpers.SeedDepartments(_context);
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 1000,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.First(c => c.CourseID == 1000);
            Assert.Equal("Test Course", retrieved.Title);
        }

        [Fact]
        public void CanAddAndRetrieveDepartment()
        {
            var dept = new Department
            {
                Name = "Science",
                Budget = 500000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var retrieved = _context.Departments.First();
            Assert.Equal("Science", retrieved.Name);
        }

        [Fact]
        public void CanAddEnrollmentWithRelationships()
        {
            TestHelpers.SeedFullData(_context);
            var enrollment = _context.Enrollments.First();
            Assert.True(enrollment.StudentID > 0);
            Assert.True(enrollment.CourseID > 0);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            TestHelpers.SeedCourses(_context);
            var instructor = _context.Instructors.First();
            var course = _context.Courses.First();

            var assignment = new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments.Find(course.CourseID, instructor.ID);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void OfficeAssignment_HasInstructorKey()
        {
            TestHelpers.SeedInstructors(_context);
            var instructor = _context.Instructors.First();
            var office = new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = "Smith 17"
            };
            _context.OfficeAssignments.Add(office);
            _context.SaveChanges();

            var retrieved = _context.OfficeAssignments.Find(instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Smith 17", retrieved.Location);
        }

        [Fact]
        public void Notification_CanBeAddedAndRetrieved()
        {
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = DateTime.Now,
                CreatedBy = "System",
                IsRead = false
            };
            _context.Notifications.Add(notification);
            _context.SaveChanges();

            var retrieved = _context.Notifications.First();
            Assert.Equal("Student", retrieved.EntityType);
        }

        [Fact]
        public void Person_FullName_ReturnsConcatenation()
        {
            var student = new Student
            {
                FirstMidName = "John",
                LastName = "Doe",
                EnrollmentDate = DateTime.Now
            };
            Assert.Equal("Doe, John", student.FullName);
        }
    }

    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_SeedsData()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
            Assert.Equal(7, context.Courses.Count());
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.True(context.CourseAssignments.Any());
            Assert.True(context.Enrollments.Any());
        }

        [Fact]
        public void Initialize_DoesNotDuplicateData_WhenCalledTwice()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            DbInitializer.Initialize(context);
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
        }
    }
}

