using ContosoUniversity.Models;
using System;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class ModelTests
    {
        #region Person / Student / Instructor

        [Fact]
        public void Student_FullName_ReturnsLastCommaFirst()
        {
            var student = new Student { FirstMidName = "Jane", LastName = "Smith", EnrollmentDate = DateTime.Now };
            Assert.Equal("Smith, Jane", student.FullName);
        }

        [Fact]
        public void Instructor_FullName_ReturnsLastCommaFirst()
        {
            var instructor = new Instructor { FirstMidName = "John", LastName = "Doe", HireDate = DateTime.Now };
            Assert.Equal("Doe, John", instructor.FullName);
        }

        [Fact]
        public void Student_IsPersonSubclass()
        {
            var student = new Student { FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now };
            Assert.IsAssignableFrom<Person>(student);
        }

        [Fact]
        public void Instructor_IsPersonSubclass()
        {
            var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Now };
            Assert.IsAssignableFrom<Person>(instructor);
        }

        #endregion

        #region ErrorViewModel

        [Fact]
        public void ErrorViewModel_ShowRequestId_TrueWhenSet()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };
            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_FalseWhenNull()
        {
            var model = new ErrorViewModel { RequestId = null };
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_FalseWhenEmpty()
        {
            var model = new ErrorViewModel { RequestId = "" };
            Assert.False(model.ShowRequestId);
        }

        #endregion

        #region EntityOperation

        [Fact]
        public void EntityOperation_HasCreateUpdateDelete()
        {
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }

        #endregion

        #region Grade

        [Fact]
        public void Grade_HasExpectedValues()
        {
            Assert.Equal(0, (int)Grade.A);
            Assert.Equal(1, (int)Grade.B);
            Assert.Equal(2, (int)Grade.C);
            Assert.Equal(3, (int)Grade.D);
            Assert.Equal(4, (int)Grade.F);
        }

        #endregion

        #region Notification

        [Fact]
        public void Notification_Properties_CanBeSet()
        {
            var now = DateTime.Now;
            var n = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "Test",
                CreatedAt = now,
                CreatedBy = "Admin",
                IsRead = true,
                ReadAt = now
            };
            Assert.Equal(1, n.Id);
            Assert.Equal("Student", n.EntityType);
            Assert.Equal("42", n.EntityId);
            Assert.Equal("CREATE", n.Operation);
            Assert.Equal("Test", n.Message);
            Assert.Equal(now, n.CreatedAt);
            Assert.Equal("Admin", n.CreatedBy);
            Assert.True(n.IsRead);
            Assert.Equal(now, n.ReadAt);
        }

        #endregion

        #region Course

        [Fact]
        public void Course_Properties_CanBeSet()
        {
            var c = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/uploads/test.jpg"
            };
            Assert.Equal(1050, c.CourseID);
            Assert.Equal("Chemistry", c.Title);
            Assert.Equal(3, c.Credits);
            Assert.Equal("/uploads/test.jpg", c.TeachingMaterialImagePath);
        }

        #endregion

        #region Department

        [Fact]
        public void Department_Properties_CanBeSet()
        {
            var d = new Department
            {
                DepartmentID = 1,
                Name = "English",
                Budget = 350000,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = 5,
                RowVersion = new byte[] { 1, 2, 3 }
            };
            Assert.Equal(1, d.DepartmentID);
            Assert.Equal("English", d.Name);
            Assert.Equal(350000, d.Budget);
            Assert.Equal(5, d.InstructorID);
        }

        #endregion

        #region Enrollment

        [Fact]
        public void Enrollment_NullableGrade()
        {
            var e = new Enrollment { EnrollmentID = 1, CourseID = 1, StudentID = 1 };
            Assert.Null(e.Grade);
            e.Grade = Grade.B;
            Assert.Equal(Grade.B, e.Grade);
        }

        #endregion

        #region OfficeAssignment

        [Fact]
        public void OfficeAssignment_Properties_CanBeSet()
        {
            var o = new OfficeAssignment { InstructorID = 1, Location = "Smith 17" };
            Assert.Equal(1, o.InstructorID);
            Assert.Equal("Smith 17", o.Location);
        }

        #endregion

        #region CourseAssignment

        [Fact]
        public void CourseAssignment_Properties_CanBeSet()
        {
            var ca = new CourseAssignment { InstructorID = 1, CourseID = 2 };
            Assert.Equal(1, ca.InstructorID);
            Assert.Equal(2, ca.CourseID);
        }

        #endregion
    }
}

